head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > E > onviewchange]<br/>키보드 또는 터치 스크롤 조작을 통해 DatePicker 컴포넌트의 선택 날짜가 변경되면 발생합니다.",
    "validation" : [
        "키보드 조작을 통해 DatePicker 컴포넌트의 선택 날짜가 변경되면 onviewchange 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (키보드 접근성 활성화 → accessibility=true)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 라벨: 수동 테스트 안내 (키보드 방향키 조작 → onviewchange -> onchange 순서 검증)
    $c.gcm.createLabel('label="[수동 테스트 안내] DatePicker 의 스핀(휠) 영역을 클릭하여 포커스를 얻은 후 위/아래 방향키로 값을 변경하면 onviewchange 이벤트가 발생합니다."', '', 'label1');

    // accessibility=true: 키보드 방향키 조작으로 스핀 컬럼 값 변경 가능
    let properties = {
        accessibility : "true"
    };

    let cList = $c.gcm.createCList(properties);

    // onviewchange 핸들러 등록 - 공통 모듈 사용
    let eList = $c.gcm.createEList(["onviewchange"]);

    await $c.gcm.createBasicDatePicker(cList, eList);
};



// 사용자의 키보드 조작으로 선택 날짜가 변경되면 발생
scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
};
